<?php
declare(strict_types=1);require_once __DIR__.'/includes/ui.php';pv_require_login();$db=pv_db();$uid=(int)$_SESSION['myid'];$events=[];$r=$db->query('SELECT * FROM events WHERE is_active=1 ORDER BY id');if($r)while($x=$r->fetch_assoc())$events[]=$x;$progress=[];$stmt=$db->prepare('SELECT event_id,progress,completed FROM event_progress WHERE owner_id=?');$stmt->bind_param('i',$uid);$stmt->execute();$rr=$stmt->get_result();while($x=$rr->fetch_assoc())$progress[(int)$x['event_id']]=$x;$stmt->close();pv_page_start('Event Center','event_center.php',true);?>
<div class="pv-game-layout"><?php pv_game_side_menu('event_center.php');?><main class="pv-main-column"><section class="pv-page pv-event-center-modern"><div class="pv-page-head"><?php nxt_page_sprites();?><div><span class="pv-eyebrow">DAWN OPERATIONS</span><h1>Event Center</h1><p class="pv-subtle">Survey the Dawn world through network operations. Track your progress and find your next destination.</p></div></div><div class="pv-grid cols-3"><?php foreach($events as $e):$p=$progress[(int)$e['id']]??['progress'=>0,'completed'=>0];?><article class="pv-card pv-event-feature" style="padding:20px"><small><?=pv_h(strtoupper((string)$e['area_name']))?></small><h2><?=pv_h((string)$e['name'])?></h2><p><?=pv_h((string)$e['description'])?></p><div class="pv-progress"><i style="width:<?=min(100,(int)$p['progress'])?>%"></i></div><strong><?=min(100,(int)$p['progress'])?>% <?=((int)$p['completed']===1)?'COMPLETE':'SYNCED'?></strong><div class="pv-actions" style="margin-top:12px"><a class="pv-button pv-button-secondary" href="<?=pv_h(pv_url('map_select.php'))?>">Open Dawn atlas</a></div></article><?php endforeach;?></div></section></main></div><?php pv_page_end(); ?>
